  console.log("[Timeline] Navigate: base_url");
  // Navigate to base URL
  await page.goto('https://www.saucedemo.com');

  // [Timeline] Assert: accepted_on_boundary
  console.log("[Timeline] Assert: accepted_on_boundary");
  // Assert accepted_on_boundary
  await expect(page).toContainText('accepted_on_boundary');
});
